# -*- coding: utf-8 -*-
"""Generate pure-ASCII UTF-8 tokens for localized prosthetic names."""
from pathlib import Path

TOKENS = {
    'LEFT': ('left', '左'),
    'RIGHT': ('right', '右'),
    'ARM': ('arm', '臂'),
    'LEG': ('leg', '腿'),
}

def escape(value):
    return ''.join('\\x%02x' % byte for byte in value.encode('utf-8'))

def main():
    lines = [
        '// Generated by tools/gen_prosthetic_names.py; do not edit escapes manually.',
        '#ifndef KENSHI_TRAINER_PROSTHETIC_NAMES_H',
        '#define KENSHI_TRAINER_PROSTHETIC_NAMES_H',
        '',
    ]
    for name, values in TOKENS.items():
        lines.append('static const char* const PROSTHETIC_%s_TOKENS[] =' % name)
        lines.append('{ %s, 0 };' % ', '.join('\"%s\"' % escape(v) for v in values))
    lines += ['', '#endif', '']
    path = Path(__file__).resolve().parents[1] / 'src/ProstheticNames.h'
    path.write_text('\n'.join(lines), encoding='ascii', newline='\n')
    print('Updated localized prosthetic name tokens')

if __name__ == '__main__':
    main()
